const AIRCON_LOGO_B64 = "data:image/png;base64,";
// Set sidebar AIRCON logo from the existing const
(function setSidebarLogo() {
  function trySet() {
    var el = document.getElementById('sidebar-logo-img');
    if (el && typeof AIRCON_LOGO_B64 !== 'undefined') {
      el.src = AIRCON_LOGO_B64;
    } else {
      setTimeout(trySet, 100);
    }
  }
  trySet();
})();

