// ════════════════════════════════════════
//  AUTH / LOGIN
// ════════════════════════════════════════
const SUPERVISOR_PIN = '1234';
let currentUser = null;

function initLogin() {
  const ll = document.getElementById('login-logo');
  if (ll && typeof AIRCON_LOGO_B64 !== 'undefined') ll.src = AIRCON_LOGO_B64;

  try {
    const saved = JSON.parse(sessionStorage.getItem('aircon_user') || 'null');
    if (saved && saved.name) {
      currentUser = saved;
      document.getElementById('login-overlay').style.display = 'none';
      applyUserRole();
      return;
    }
  } catch {}

  // Populate name dropdown from technicians DB
  const sel = document.getElementById('login-name');
  if (sel && sel.options.length <= 1) {
    getTechniciansDB().forEach(t => {
      const full = typeof t === 'string' ? t : '';
      if (!full) return;
      const name = full.split(/\s{2,}/)[0] || full;
      const opt = document.createElement('option');
      opt.value = name; opt.textContent = name;
      sel.appendChild(opt);
    });
  }
  document.getElementById('login-overlay').style.display = 'flex';
}

function showPINField() {
  const row = document.getElementById('pin-row');
  if (row) { row.style.display = 'block'; document.getElementById('login-pin')?.focus(); }
}

function loginAs(role) {
  try {
    const name = document.getElementById('login-name')?.value;
    if (!name) { showLoginError('Select your name'); return; }
    currentUser = { name, role };
    sessionStorage.setItem('aircon_user', JSON.stringify(currentUser));
    // Hide login
    const overlay = document.getElementById('login-overlay');
    if (overlay) overlay.style.display = 'none';
    // Init app
    try { switchView('fr'); } catch(e){ console.error('switchView error:', e); }
    try { applyUserRole(); } catch(e){ console.error('applyUserRole error:', e); }
    try { initGroqKeySidebar(); } catch(e){}
    snack('Welcome, ' + name + '!');
  } catch(err) {
    console.error('loginAs error:', err);
    alert('Login error: ' + err.message);
  }
}

function showLoginError(msg) {
  const el = document.getElementById('login-error');
  if (el) { el.textContent = msg; el.style.display = 'block'; }
}

function applyUserRole() {
  if (!currentUser) return;
  const isSup = currentUser.role === 'supervisor';
  const supNav = document.getElementById('nav-super');
  if (supNav) supNav.style.display = isSup ? 'flex' : 'none';
  const roleEl = document.getElementById('current-user-info');
  if (roleEl) { roleEl.textContent = currentUser.name + ' · ' + currentUser.role; roleEl.style.display = 'block'; }

  // Auto-fill first tech row from logged-in user
  if (currentUser.name) {
    const doFill = () => {
      try {
        if (typeof techRows === 'undefined' || !techRows.length) { setTimeout(doFill,400); return; }
        const id = techRows[0];
        const dd = dropdownRegistry['tech-'+id] || dropdownRegistry['dd-tech-'+id];
        if (!dd) { setTimeout(doFill,400); return; }
        if (dd.selected) return;
        const firstName = currentUser.name.split(' ')[0].toLowerCase();
        const match = getTechniciansDB().find(t => (typeof t==='string'?t:'').toLowerCase().includes(firstName));
        if (!match) return;
        const displayName = match.split(/  +/)[0];
        dd.selected=match; if(dd.input)dd.input.value=displayName; if(dd.wrap)dd.wrap.classList.add('has-value');
        if(typeof techData!=='undefined'&&techData[id]) techData[id].name=match;
        if(typeof updateReportNumber==='function') updateReportNumber();
        const bdg=document.getElementById('badge-'+id);
        if(bdg){ const pts=match.split(/  +/); bdg.value=pts[1]||''; }
      } catch(e){ console.warn('doFill:',e); }
    };
    setTimeout(doFill, 800);
    setTimeout(doFill, 1500);
  }
}

function logout() { sessionStorage.removeItem('aircon_user'); currentUser = null; location.reload(); }


