// ════════════════════════════════════════
//  SYNCRUDE SHIFT CYCLE
// ════════════════════════════════════════
// Anchor date: March 31, 2026 — cycle position 0 (501N + 502D)
const SYNCRUDE_ANCHOR = new Date(2026, 2, 31);
const SYNCRUDE_CYCLE = [
  {night:'501N', day:'502D'},
  {night:'502N', day:'503D'},
  {night:'503N', day:'504D'},
  {night:'504N', day:'501D'},
];

// Default truck assignments — keyed by surname (case-insensitive substring match)
const TECH_TRUCK_MAP = {
  'nazarenko': 'T-222',
  'aksonkin':  'T-223',
};

// Shift leaders — from the Syncrude calendar app (LEADERS dict)
// Multiple leaders per shift; first one is used as default auto-fill
const SHIFT_LEADERS = {
  '501N': ['Cecil Toner'],
  '501D': ['Cecil Toner'],
  '502N': ['Jamie Perry', 'Christopher Walker'],
  '502D': ['Jamie Perry', 'Christopher Walker'],
  '503N': ['Joel Hoilund', 'Michael Goman'],
  '503D': ['Joel Hoilund', 'Michael Goman'],
  '504N': ['Michael Latcham', 'Chris Snow'],
  '504D': ['Michael Latcham', 'Chris Snow'],
};

function getSyncrudeShiftForDate(dateStr, opts) {
  // Modes:
  //   default (no opts)  — use the REAL current moment to determine slot date + shift type
  //   {forDate: 'YYYY-MM-DD'}  — explicit date (used by Time Card), default day-shift
  //   {forDate, type: 'day'|'night'} — fully explicit (Time Card with shift override)
  opts = opts || {};
  let slotDate, shiftType;

  if (opts.forDate) {
    const [y, m, d] = opts.forDate.split('-').map(Number);
    slotDate = new Date(y, m - 1, d);
    shiftType = opts.type || 'day';
  } else {
    // ALWAYS use current real time for shift detection
    // (ignore dateStr — it's what the form says, but reality is what counts)
    const now = new Date();
    const todayMid = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const min = now.getHours() * 60 + now.getMinutes();
    const DAY_START = 7 * 60 + 30;    // 07:30
    const NIGHT_START = 19 * 60 + 30; // 19:30

    if (min >= DAY_START && min < NIGHT_START) {
      shiftType = 'day';
      slotDate = todayMid;
    } else if (min >= NIGHT_START) {
      shiftType = 'night';
      slotDate = todayMid;          // night that started today at 19:30
    } else {
      shiftType = 'night';
      slotDate = new Date(todayMid);
      slotDate.setDate(slotDate.getDate() - 1);  // night started yesterday
    }
  }

  const diffDays = Math.round((slotDate - SYNCRUDE_ANCHOR) / 86400000);
  const pos = ((diffDays % 12) + 12) % 12;
  const blockIdx = Math.floor(pos / 3);
  const block = SYNCRUDE_CYCLE[blockIdx];
  const shift = shiftType === 'night' ? block.night : block.day;
  const leaders = SHIFT_LEADERS[shift] || [];
  return { shift, leaders, leader: leaders[0] || '', shiftType, slotDate };
}

function getTechInitials(techName) {
  if (!techName) return '';
  // Extract first 2 capital initials from the name part (before any ID like "PA-90446064")
  const cleanName = techName.split(/\s{2,}/)[0].trim();   // split on double-space (separator before ID)
  const parts = cleanName.split(/\s+/).filter(Boolean);
  if (parts.length === 0) return '';
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

function getReportPrefix() {
  if (jobType === 'HVAC') return 'HV';
  if (jobType === 'F/S')  return 'FS';
  if (jobType === 'F/S ')  return 'FS';  // trim space
  if (jobType === 'FS')   return 'FS';
  return 'XX';  // job type not selected yet
}

function makeUniqueReportNum(base) {
  // Returns base if unused, otherwise base-2, base-3, etc.
  const all = loadSavedReports();
  const currentNum = (document.getElementById('f-reportnum') || {}).value || '';
  // Collect all taken numbers except the one currently in the form (we're editing it)
  const taken = new Set(all.map(r => r.reportNum).filter(n => n && n !== currentNum));
  if (!taken.has(base)) return base;
  for (let i = 2; i <= 99; i++) {
    const candidate = `${base}-${i}`;
    if (!taken.has(candidate)) return candidate;
  }
  return `${base}-?`;
}

function updateReportNumber() {
  // Don't regenerate number when editing an existing report
  const rnEl = document.getElementById('f-reportnum');
  if (rnEl && rnEl.dataset.locked === 'true') return;
  const prefix = getReportPrefix();
  const unitSel = dropdownRegistry['unit'] && dropdownRegistry['unit'].selected;
  const unit = unitSel ? unitSel.unit : 'XX';
  const dateStr = (document.getElementById('f-date') || {}).value || '';
  const yymmdd = dateStr ? dateStr.replace(/-/g, '').slice(2) : 'YYMMDD';
  let initials = 'XX';
  for (const id of techRows) {
    const name = techData[id] && techData[id].name;
    if (name) { initials = getTechInitials(name); break; }
  }
  const base = `${prefix}-${unit}-${yymmdd}-${initials}`;
  // Only generate unique number if we are NOT editing an already-saved report
  // (i.e. the current displayed number exists in DB — keep it as-is)
  const currentNum = (document.getElementById('f-reportnum') || {}).value || '';
  const all = loadSavedReports();
  const isEditing = currentNum && all.some(r => r.reportNum === currentNum);
  const num = isEditing ? currentNum : makeUniqueReportNum(base);
  const el = document.getElementById('f-reportnum');
  if (el) el.value = num;
}

function onDateChange() {
  applySyncrudeAutoFill();
  updateReportNumber();
}

function rebuildContactDropdown(leaders, defaultLeader) {
  // Remove old dropdown if it exists in body (portal cleanup)
  const old = dropdownRegistry['contact'];
  if (old && old.dropdown && old.dropdown.parentNode === document.body) {
    old.dropdown.remove();
  }
  delete dropdownRegistry['contact'];

  createDropdown({
    id: 'contact',
    container: 'dd-contact',
    items: leaders && leaders.length ? leaders : [],
    placeholder: leaders && leaders.length === 1
      ? `Selected: ${leaders[0]} — click to change or type custom`
      : 'Select shift leader or type custom name…',
    allowCustom: true,
    initialValue: defaultLeader || '',
    onSelect: (v) => {
      // value handled internally
    }
  });

  // Mark the dropdown wrapper visually if leader was auto-set
  if (defaultLeader) {
    const dd = dropdownRegistry['contact'];
    if (dd) {
      dd.selected = defaultLeader;
      dd.wrap.classList.add('auto-filled-flash');
      setTimeout(() => dd.wrap.classList.remove('auto-filled-flash'), 1200);
    }
  }
}

// ════════════════════════════════════════
//  UNIVERSAL SEARCHABLE DROPDOWN
// ════════════════════════════════════════
const dropdownRegistry = {};
let openDropdownId = null;

/**
 * Create a searchable dropdown.
 * options: { id, container, items, placeholder, valueKey?, displayFn?, subFn?, onSelect, allowCustom? }
 */
function createDropdown(opts) {
  const {
    id, container, items, placeholder = 'Select…',
    valueKey, displayFn, subFn,
    onSelect, allowCustom = false, initialValue = ''
  } = opts;

  const target = (typeof container === 'string') ? document.getElementById(container) : container;
  if (!target) return;

  // wrapper
  const wrap = document.createElement('div');
  wrap.className = 'sd-wrap';
  wrap.id = `sd-${id}`;
  wrap.innerHTML = `
    <div class="sd-input-wrap">
      <input type="text" class="sd-input" placeholder="${placeholder}" readonly value="${initialValue}">
      <button type="button" class="sd-clear" title="Clear">✕</button>
      <span class="sd-arrow">▼</span>
    </div>
    <div class="sd-dropdown">
      <div class="sd-search-row">
        <span class="sd-search-icon">🔍</span>
        <input type="text" class="sd-search" placeholder="Type any character to filter…">
      </div>
      <div class="sd-count"></div>
      <div class="sd-list"></div>
    </div>
  `;
  target.innerHTML = '';
  target.appendChild(wrap);

  const input = wrap.querySelector('.sd-input');
  const clearBtn = wrap.querySelector('.sd-clear');
  const dropdown = wrap.querySelector('.sd-dropdown');
  const search = wrap.querySelector('.sd-search');
  const list = wrap.querySelector('.sd-list');
  const countEl = wrap.querySelector('.sd-count');

  const state = {
    items, displayFn, subFn, valueKey,
    selected: null, filtered: items.slice(),
    activeIdx: -1, allowCustom, onSelect, id
  };
  dropdownRegistry[id] = state;
  state.wrap = wrap;
  state.input = input;
  state.search = search;
  state.list = list;
  state.countEl = countEl;
  state.clearBtn = clearBtn;
  state.dropdown = dropdown;

  // initial value handling
  if (initialValue) wrap.classList.add('has-value');

  // Open on click
  input.addEventListener('click', () => openDropdown(id));
  input.addEventListener('focus', () => openDropdown(id));

  clearBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    state.selected = null;
    input.value = '';
    wrap.classList.remove('has-value');
    if (state.onSelect) state.onSelect(null);
    // Update required indicator
    if (wrap.classList.contains('req')) {
      wrap.classList.remove('req-ok');
    }
  });

  search.addEventListener('input', () => {
    filterDropdown(id, search.value);
  });

  search.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); moveActive(id, 1); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); moveActive(id, -1); }
    else if (e.key === 'Enter') {
      e.preventDefault();
      if (state.activeIdx >= 0 && state.filtered[state.activeIdx]) {
        selectItem(id, state.filtered[state.activeIdx]);
      } else if (allowCustom && search.value.trim()) {
        const custom = search.value.trim();
        input.value = custom;
        wrap.classList.add('has-value');
        if (state.onSelect) state.onSelect({_custom: true, value: custom});
        closeDropdown();
      }
    }
    else if (e.key === 'Escape') closeDropdown();
  });

  renderList(id);
}

function defaultDisplay(item, valueKey) {
  if (typeof item === 'string') return item;
  if (valueKey && item[valueKey] !== undefined) return item[valueKey];
  return String(item);
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function highlight(text, query) {
  if (!query) return escapeHtml(text);
  const safe = escapeHtml(text);
  const safeQ = escapeHtml(query).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  try {
    return safe.replace(new RegExp(safeQ, 'gi'), m => `<mark>${m}</mark>`);
  } catch(e) { return safe; }
}

function renderList(id) {
  const s = dropdownRegistry[id];
  if (!s) return;
  const q = s.search.value.trim();
  const items = s.filtered;
  s.countEl.textContent = `${items.length} of ${s.items.length}`;

  if (!items.length) {
    s.list.innerHTML = `<div class="sd-empty">No matches${s.allowCustom ? ' — press Enter to use custom value' : ''}</div>`;
    return;
  }

  // Limit rendering for performance
  const MAX = 200;
  const slice = items.slice(0, MAX);

  s.list.innerHTML = slice.map((item, idx) => {
    const display = s.displayFn ? s.displayFn(item) : defaultDisplay(item, s.valueKey);
    const sub = s.subFn ? s.subFn(item) : '';
    const activeCls = idx === s.activeIdx ? ' active' : '';
    return `<div class="sd-option${activeCls}" data-idx="${idx}">
      <div>${highlight(display, q)}</div>
      ${sub ? `<div class="sd-sub">${highlight(sub, q)}</div>` : ''}
    </div>`;
  }).join('') + (items.length > MAX ? `<div class="sd-empty">…and ${items.length - MAX} more — refine your search</div>` : '');

  // Bind click
  s.list.querySelectorAll('.sd-option').forEach(el => {
    el.addEventListener('mousedown', (e) => {
      e.preventDefault();
      const idx = parseInt(el.dataset.idx, 10);
      selectItem(id, slice[idx]);
    });
  });
}

function filterDropdown(id, q) {
  const s = dropdownRegistry[id];
  if (!s) return;
  const query = q.trim().toLowerCase();
  if (!query) {
    s.filtered = s.items.slice();
  } else {
    s.filtered = s.items.filter(item => {
      const display = s.displayFn ? s.displayFn(item) : defaultDisplay(item, s.valueKey);
      const sub = s.subFn ? s.subFn(item) : '';
      const haystack = (display + ' ' + sub).toLowerCase();
      // Match any character/substring anywhere in the item
      return haystack.includes(query);
    });
  }
  s.activeIdx = s.filtered.length ? 0 : -1;
  renderList(id);
}

function moveActive(id, dir) {
  const s = dropdownRegistry[id];
  if (!s || !s.filtered.length) return;
  s.activeIdx = (s.activeIdx + dir + s.filtered.length) % s.filtered.length;
  renderList(id);
  // scroll into view
  const active = s.list.querySelector('.sd-option.active');
  if (active) active.scrollIntoView({block:'nearest'});
}

function selectItem(id, item) {
  const s = dropdownRegistry[id];
  if (!s) return;
  s.selected = item;
  const display = s.displayFn ? s.displayFn(item) : defaultDisplay(item, s.valueKey);
  s.input.value = display;
  s.wrap.classList.add('has-value');
  if (s.onSelect) s.onSelect(item);
  closeDropdown();
  // Update required field highlighting
  setTimeout(() => rfApplyDD(id), 30);
}

function openDropdown(id) {
  if (openDropdownId && openDropdownId !== id) closeDropdown();
  const s = dropdownRegistry[id];
  if (!s) return;

  // Move dropdown to body so it's not clipped by parent overflow
  if (s.dropdown.parentNode !== document.body) {
    document.body.appendChild(s.dropdown);
  }

  s.wrap.classList.add('open');
  openDropdownId = id;

  // Position dropdown relative to input
  positionDropdown(id);

  setTimeout(() => s.search.focus(), 50);
  s.search.value = '';
  filterDropdown(id, '');

  // Listen for scroll/resize
  window.addEventListener('scroll', repositionOpen, true);
  window.addEventListener('resize', repositionOpen);
}

function positionDropdown(id) {
  const s = dropdownRegistry[id];
  if (!s) return;
  s.dropdown.style.display = 'flex';
  const rect = s.input.getBoundingClientRect();
  const dropdownHeight = 360; // approximate max
  const spaceBelow = window.innerHeight - rect.bottom;
  const spaceAbove = rect.top;
  const showAbove = spaceBelow < dropdownHeight && spaceAbove > spaceBelow;

  s.dropdown.style.left = rect.left + 'px';
  s.dropdown.style.width = Math.max(rect.width, 280) + 'px';

  if (showAbove) {
    s.dropdown.style.top = 'auto';
    s.dropdown.style.bottom = (window.innerHeight - rect.top + 4) + 'px';
    s.dropdown.style.maxHeight = (spaceAbove - 16) + 'px';
  } else {
    s.dropdown.style.bottom = 'auto';
    s.dropdown.style.top = (rect.bottom + 4) + 'px';
    s.dropdown.style.maxHeight = (spaceBelow - 16) + 'px';
  }
}

function repositionOpen() {
  if (openDropdownId) positionDropdown(openDropdownId);
}

function closeDropdown() {
  if (!openDropdownId) return;
  const s = dropdownRegistry[openDropdownId];
  if (s) { s.wrap.classList.remove('open'); s.dropdown.style.display = 'none'; }
  openDropdownId = null;
  window.removeEventListener('scroll', repositionOpen, true);
  window.removeEventListener('resize', repositionOpen);
}

document.addEventListener('mousedown', (e) => {
  if (!openDropdownId) return;
  const s = dropdownRegistry[openDropdownId];
  if (!s) return;
  // Don't close if click is inside the wrapper OR inside the dropdown (since it's now in body)
  if (s.wrap.contains(e.target) || s.dropdown.contains(e.target)) return;
  closeDropdown();
});

