function getEffectiveReportDate() {
  // If now is between 00:00 and 07:30, report date should be YESTERDAY
  // (the night shift that started yesterday at 19:30 is still active).
  // Otherwise (07:30 onwards) report date = today.
  const now = new Date();
  const min = now.getHours() * 60 + now.getMinutes();
  const NIGHT_END = 7 * 60 + 30; // 07:30
  const d = new Date(now);
  if (min < NIGHT_END) d.setDate(d.getDate() - 1);
  return d.toISOString().split('T')[0];
}

