// ── SAVE CURRENT AS PART SET ──
function saveCurrentAsPartSet() {
  const parts = partRows.map(id => ({
    qty: document.getElementById(`qty-${id}`)?.value || '1',
    partNo: partData[id]?.partNo || '',
    desc: document.getElementById(`pdesc-${id}`)?.value || ''
  })).filter(p => p.partNo || p.desc);
  if (!parts.length) { snack('No parts to save'); return; }
  const name = prompt('Name for this part set:', 'Part Set ' + (getPartSets().length + 1));
  if (!name) return;
  const sets = getPartSets();
  sets.push({name, parts});
  savePartSets(sets);
  renderPartSetButtons();
  snack(`✔ Saved part set: ${name}`);
}

// ── APPLY PART SET ──

function deletePartSet(idx) {
  const sets = getPartSets();
  if (!confirm(`Delete part set "${sets[idx]?.name}"?`)) return;
  sets.splice(idx, 1);
  savePartSets(sets);
  renderPartSetButtons();
  snack('Part set deleted');
}

// ── TEMPLATES ──
function saveCurrentAsTemplate() {
  const data = collectData();
  const name = prompt('Template name:', data.c1 ? data.c1.slice(0,30) : 'Template ' + (getTemplates().length+1));
  if (!name) return;
  const tpl = {name, c1: data.c1, c2: data.c2, c3: data.c3, parts: data.parts, complications: data.complications, type: data.type};
  const templates = getTemplates();
  templates.push(tpl);
  saveTemplates(templates);
  renderTemplateButtons();
  snack(`✔ Template saved: ${name}`);
}

function deleteTemplate(idx) {
  const templates = getTemplates();
  if (!confirm(`Delete template "${templates[idx]?.name}"?`)) return;
  templates.splice(idx, 1);
  saveTemplates(templates);
  renderTemplateButtons();
  snack('Template deleted');
}

function renderTemplateSelect() {
  const sel = document.getElementById('template-select');
  if (!sel) return;
  const templates = getTemplates();
  const current = sel.value;
  sel.innerHTML = '<option value="">— Select template to apply —</option>' +
    templates.map((t, i) => `<option value="${i}">${escapeHtml(t.name)}</option>`).join('');
  if (current) sel.value = current;
  // Also populate truck2 dropdown
  if (sel2) {
    const cur2 = sel2.value;
    while (sel2.options.length > 1) sel2.remove(1);
    [...trucks].filter(Boolean).sort().forEach(t => {
      const opt = document.createElement('option');
      opt.value = t; opt.textContent = t; sel2.appendChild(opt);
    });
    if (cur2) sel2.value = cur2;
  }
}

function applySelectedTemplate() {
  const sel = document.getElementById('template-select');
  const idx = sel ? parseInt(sel.value) : -1;
  if (isNaN(idx) || idx < 0) { snack('Select a template first'); return; }
  applyTemplate(idx);
}

function deleteSelectedTemplate() {
  const sel = document.getElementById('template-select');
  const idx = sel ? parseInt(sel.value) : -1;
  if (isNaN(idx) || idx < 0) { snack('Select a template to delete'); return; }
  deleteTemplate(idx);
}

