function renderDatabaseView() {
  const dbView = document.getElementById('view-db');
  if (!dbView) return;
  // Already rendered dynamically via switchView
}

function dbUpdateField(type, idx, field, val) {
  if (!window._dbEditItems) return;
  if (typeof window._dbEditItems[idx] === 'string') {
    window._dbEditItems[idx] = val;
  } else {
    window._dbEditItems[idx][field] = val;
  }
}

function rebuildDropdownsAfterDBSave(type) {
  // Fully rebuild affected dropdowns with fresh data from localStorage
  try {
    if (type === 'equipment') {
      const freshData = getEquipmentDB();
      // Delete and re-create the unit dropdown
      if (dropdownRegistry['unit']) {
        delete dropdownRegistry['unit'];
      }
      const container = document.getElementById('dd-unit');
      if (container) {
        container.innerHTML = '';
        createDropdown({
          id: 'unit',
          container: 'dd-unit',
          items: freshData,
          placeholder: 'Search unit #…',
          displayFn: e => e.unit,
          subFn: e => (e.make||'') + ' ' + (e.model||''),
          onSelect: eq => {
            if (!eq) {
              ['f-make','f-model','f-serial','f-category'].forEach(id => {
                const el = document.getElementById(id); if (el) el.value = '';
              });
              updateReportNumber();
              if (typeof rfApplyDD === 'function') rfApplyDD('unit');
              return;
            }
            const data = eq._custom ? {} : eq;
            document.getElementById('f-make').value     = data.make     || '';
            document.getElementById('f-model').value    = data.model    || '';
            document.getElementById('f-serial').value   = data.serial   || '';
            document.getElementById('f-category').value = data.category || '';
            if (data.category) autoFillPO(data.category);
            updateReportNumber();
            if (typeof rfApplyDD === 'function') rfApplyDD('unit');
          }
        });
        snack('✔ Unit dropdown updated — ' + freshData.length + ' units available');
      }
    }
    if (type === 'technicians') {
      const freshData = getTechniciansDB();
      // Rebuild all tech dropdowns in existing tech rows
      if (typeof techRows !== 'undefined') {
        techRows.forEach(id => {
          const dd = dropdownRegistry['tech-' + id];
          if (dd) dd.allItems = freshData;
        });
      }
      // Rebuild login dropdown
      const loginSel = document.getElementById('login-name');
      if (loginSel) {
        const currentVal = loginSel.value;
        while (loginSel.options.length > 1) loginSel.remove(1);
        freshData.forEach(t => {
          const name = (typeof t === 'string' ? t : '').split(/  +/)[0];
          if (!name) return;
          const opt = document.createElement('option');
          opt.value = name; opt.textContent = name;
          loginSel.appendChild(opt);
        });
        loginSel.value = currentVal;
      }
    }
    if (type === 'parts') {
      const freshData = getPartsDB();
      Object.keys(dropdownRegistry).forEach(key => {
        if (key.startsWith('part-')) {
          const dd = dropdownRegistry[key];
          if (dd) dd.allItems = freshData;
        }
      });
    }
  } catch(e) { console.warn('rebuildDropdowns error:', e); }
}


function dbUpdateRow(idx, field, val, type) {
  const items = type==='parts' ? getPartsDB() :
    type==='technicians' ? getTechniciansDB() :
    type==='trucks' ? getTrucksDB() : getEquipmentDB();
  const isStrArr = items.length && typeof items[0] === 'string';
  const rows = isStrArr ? items.map(x=>({value:x})) : items;
  if (rows[idx]) {
    rows[idx][field] = val;
    const saveArr = isStrArr ? rows.map(r=>r.value) : rows;
    const key = DB_KEYS[type];
    localStorage.setItem(key, JSON.stringify(saveArr));
  }
}

function dbDeleteRow(idx, type) {
  const key = DB_KEYS[type];
  const items = type==='parts' ? getPartsDB() :
    type==='technicians' ? getTechniciansDB() :
    type==='trucks' ? getTrucksDB() : getEquipmentDB();
  items.splice(idx, 1);
  localStorage.setItem(key, JSON.stringify(items));
  renderDBTable(type);
}

function dbAddRow(type) {
  const key = DB_KEYS[type];
  const items = type==='parts' ? getPartsDB() :
    type==='technicians' ? getTechniciansDB() :
    type==='trucks' ? getTrucksDB() : getEquipmentDB();
  if (type==='parts') items.push({partNo:'', desc:''});
  else if (type==='equipment') items.push({unit:'',make:'',model:'',serial:'',category:''});
  else items.push('');
  localStorage.setItem(key, JSON.stringify(items));
  renderDBTable(type);
}

function dbResetToDefault(type) {
  if (!confirm(`Reset ${type} database to factory defaults? Custom entries will be lost.`)) return;
  localStorage.removeItem(DB_KEYS[type]);
  renderDBTable(type);
  snack(`${type} reset to defaults`);
}

