function flashElement(id) {
  const el = document.getElementById(id);
  if (!el) return;
  el.classList.add('flash-red');
  setTimeout(() => el.classList.remove('flash-red'), 2400);
}

function clearAllValidation() {
  // Only clear flash animations — NOT req-err (those persist until field is filled)
  document.querySelectorAll('.field-invalid, .comp-grid-invalid, .status-row-invalid, .flash-red, .flash-red-block, .validation-error, .validation-error-pulse')
    .forEach(el => el.classList.remove('field-invalid','comp-grid-invalid','status-row-invalid','flash-red','flash-red-block','validation-error','validation-error-pulse'));
  const b = document.getElementById('validation-banner');
  if (b) b.remove();
}

// Hook handlers to remove banner once all fields look valid
function recheckValidation() {
  const r = validateForm();
  if (r.ok) {
    const b = document.getElementById('validation-banner');
    if (b) b.remove();
  }
}

