const STORAGE_KEY = 'aircontech_field_reports_v1';

function deleteSavedReport(idx) {
  const allReps = loadSavedReports();
  const report = allReps[idx];
  if (report && report.reportNum) syncDeleteReport(report.reportNum);
  const all = loadSavedReports();
  if (!confirm(`Delete report ${all[idx]?.reportNum || ''}?`)) return;
  all.splice(idx, 1);
  saveSavedReports(all);
  renderSavedList();
  snack('Deleted');
}

function exportAllData() {
  const all = loadSavedReports();
  if (!all.length) { snack('No reports to export'); return; }
  const blob = new Blob([JSON.stringify(all, null, 2)], {type: 'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `field-reports-${new Date().toISOString().split('T')[0]}.json`;
  a.click();
  URL.revokeObjectURL(url);
  snack(`Exported ${all.length} reports`);
}

function importData(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const imported = JSON.parse(e.target.result);
      if (!Array.isArray(imported)) throw new Error('Invalid format');
      const existing = loadSavedReports();
      const map = new Map();
      [...existing, ...imported].forEach(r => {
        const key = r.reportNum || r.savedAt || JSON.stringify(r).slice(0,50);
        map.set(key, r);
      });
      const merged = [...map.values()];
      saveSavedReports(merged);
      renderSavedList();
      snack(`Imported. Total: ${merged.length}`);
    } catch(err) { snack('⚠ Import failed: ' + err.message); }
  };
  reader.readAsText(file);
  event.target.value = '';
}

