function switchView(view) {
  window._currentView = view;
  // Update Save button appearance
  var saveBtn = document.getElementById('hdr-save-btn');
  if (saveBtn) {
    if (view === 'fr' || view === 'inhaus') {
      saveBtn.style.background = 'rgba(255,255,255,.25)';
      saveBtn.style.opacity = '1';
      saveBtn.title = view === 'inhaus' ? 'Save Inhaus Report' : 'Save Field Report';
    } else {
      saveBtn.style.background = 'rgba(255,255,255,.08)';
      saveBtn.style.opacity = '0.5';
      saveBtn.title = 'Switch to Field Report to save';
    }
  }
  ['fr','saved','tc','db','inhaus','super'].forEach(v => {
    const pane = document.getElementById(`view-${v}`);
    const nav  = document.getElementById(`nav-${v}`);
    if (pane) pane.style.display = (v === view) ? 'block' : 'none';
    if (nav)  nav.classList.toggle('active', v === view);
  });
  const frNav = document.getElementById('fr-nav-section');
  if (frNav) frNav.style.display = (view === 'fr') ? 'block' : 'none';
  if (view === 'saved')  renderSavedList();
  if (view === 'tc')     { initTimeCardView(); setTimeout(tcPopulateTruckDropdown, 300); }
  if (view === 'db')     renderDBTable('parts');
  if (view === 'super')  { setTimeout(function(){ if(typeof initSuperFilterTechs==='function') initSuperFilterTechs(); if(typeof renderSuggestionsPanel==='function') renderSuggestionsPanel(); }, 100); }
  if (view === 'inhaus') {
    if (!window._editingIhFrNum) {
    var _frNum=document.getElementById('f-reportnum')?.value||'';
    var _linked=_frNum?getLinkedInhausReport(_frNum):null;
    if (_linked) { window._editingIhFrNum=_linked.frNum; setTimeout(()=>{if(typeof ihLoadSavedReport==='function')ihLoadSavedReport(_linked.frNum);},100); }
    else { try{ihAutoFill();}catch(e){} }
  }
    setTimeout(() => {
      try { ihCheckAllExpiry(); } catch(e) {}  // restore expiry warnings
      try { ihPopulateSavedSelect(); } catch(e) {}
      const c = document.getElementById('ih-inspectors');
      if (c && c.children.length === 0) ihAutoFill();
    }, 100);
  }
}

