//  TIME CARD
// ════════════════════════════════════════
let timeCardInited = false;
let timeCardRows = []; // [{id, fr, job, start, end}]

function generateTimeOptions() {
  // 10-minute increments from 00:00 to 23:50
  const opts = [];
  for (let h = 0; h < 24; h++) {
    for (let m = 0; m < 60; m += 10) {
      opts.push(`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`);
    }
  }
  return opts;
}

function updateDefaultShiftStart() {
  const shiftDD = dropdownRegistry['tc-shift'];
  const shift = shiftDD ? (shiftDD.selected || shiftDD.input.value || '') : '';
  const isNight = shift && shift.endsWith('N');
  const startInput = document.getElementById('tc-shift-start');
  if (startInput && !startInput.dataset.userSet) {
    startInput.value = isNight ? '19:30' : '07:30';
  }
}

function distributeEqually() {
  if (!timeCardRows.length) { snack('No reports to distribute over'); return; }
  const startInput = document.getElementById('tc-shift-start');
  const startTime = startInput.value || '07:30';
  const totalMinutes = 12 * 60; // 12 hours mandatory
  const perRow = Math.floor(totalMinutes / timeCardRows.length / 10) * 10; // round to 10-min

  const [sh, sm] = startTime.split(':').map(Number);
  let currentMin = sh * 60 + sm;

  timeCardRows.forEach((r, idx) => {
    const startH = Math.floor(currentMin / 60) % 24;
    const startM = currentMin % 60;
    r.start = `${String(startH).padStart(2,'0')}:${String(startM).padStart(2,'0')}`;
    // Last row gets remainder to ensure exactly 12h total
    const dur = (idx === timeCardRows.length - 1) ? (totalMinutes - perRow * (timeCardRows.length - 1)) : perRow;
    currentMin += dur;
    const endH = Math.floor(currentMin / 60) % 24;
    const endM = currentMin % 60;
    r.end = `${String(endH).padStart(2,'0')}:${String(endM).padStart(2,'0')}`;
  });

  renderTimeCardRows();
  syncTimeCardToReports();
  snack(`✔ Distributed 12h across ${timeCardRows.length} report${timeCardRows.length===1?'':'s'}`);
}

