// ════════════════════════════════════════
//  DB CHANGE SUGGESTIONS (Tech → Supervisor)
// ════════════════════════════════════════
const DB_SUGGESTIONS_KEY = 'aircon_db_suggestions_v1';

function getDbSuggestions() {
  try { return JSON.parse(localStorage.getItem(DB_SUGGESTIONS_KEY)||'[]'); } catch { return []; }
}
function saveDbSuggestions(arr) { localStorage.setItem(DB_SUGGESTIONS_KEY, JSON.stringify(arr)); }

function suggestDbChange(type, action, value, note) {
  const sug = {
    id: Date.now(),
    type,      // 'parts','technicians','trucks','equipment'
    action,    // 'add' or 'remove'
    value,     // the item value
    note,      // optional note
    by: currentUser?.name || 'Unknown',
    at: new Date().toISOString(),
    status: 'pending'
  };
  const all = getDbSuggestions();
  all.unshift(sug);
  saveDbSuggestions(all);
  snack('✔ Suggestion sent to supervisor');
}

function pendingSuggestionsCount() {
  return getDbSuggestions().filter(s => s.status === 'pending').length;
}

function approveSuggestion(id) {
  const all = getDbSuggestions();
  const sug = all.find(s => s.id === id);
  if (!sug) return;
  sug.status = 'approved';
  sug.approvedAt = new Date().toISOString();

  // Apply the change
  const dbMap = {
    parts:       { get: getPartsDB,       key: DB_KEYS.parts },
    technicians: { get: getTechniciansDB,  key: DB_KEYS.technicians },
    trucks:      { get: getTrucksDB,       key: DB_KEYS.trucks },
    equipment:   { get: getEquipmentDB,    key: DB_KEYS.equipment },
  };
  const db = dbMap[sug.type];
  if (db) {
    let items = db.get();
    if (sug.action === 'add') {
      if (!items.some(i => JSON.stringify(i) === JSON.stringify(sug.value))) items.push(sug.value);
    } else if (sug.action === 'remove') {
      items = items.filter(i => JSON.stringify(i) !== JSON.stringify(sug.value));
    }
    localStorage.setItem(db.key, JSON.stringify(items));
  }
  saveDbSuggestions(all);
  snack('✔ Change approved and applied');
  renderSuggestionsPanel();
}

function rejectSuggestion(id) {
  const all = getDbSuggestions();
  const sug = all.find(s => s.id === id);
  if (sug) { sug.status = 'rejected'; sug.rejectedAt = new Date().toISOString(); }
  saveDbSuggestions(all);
  snack('Suggestion rejected');
  renderSuggestionsPanel();
}

// ── Tech suggestion dialog ─────────────────────────────────────────────
function openSuggestDialog(type) {
  const typeLabels = { parts:'Part', technicians:'Technician', trucks:'Truck', equipment:'Equipment' };
  const items = type === 'parts' ? getPartsDB() :
                type === 'technicians' ? getTechniciansDB() :
                type === 'trucks' ? getTrucksDB() : getEquipmentDB();
  const opts = items.map((it,i) => {
    const label = typeof it === 'string' ? it : (it.partNo||it.unit||JSON.stringify(it));
    return `<option value="${i}">${escapeHtml(label.substring(0,50))}</option>`;
  }).join('');

  const modal = document.createElement('div');
  modal.id = 'suggest-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9000;display:flex;align-items:center;justify-content:center;padding:20px';
  modal.innerHTML = `
    <div style="background:#fff;border-radius:14px;padding:28px;width:100%;max-width:440px;box-shadow:0 8px 40px rgba(0,0,0,.3)">
      <h3 style="margin-bottom:16px;color:var(--navy)">Suggest ${typeLabels[type]} Change</h3>
      <div class="form-group" style="margin-bottom:12px">
        <label>Action</label>
        <div style="display:flex;gap:10px;margin-top:6px">
          <label style="display:flex;align-items:center;gap:6px;cursor:pointer">
            <input type="radio" name="sug-action" value="add" checked> ➕ Add new
          </label>
          <label style="display:flex;align-items:center;gap:6px;cursor:pointer">
            <input type="radio" name="sug-action" value="remove"> ➖ Remove existing
          </label>
        </div>
      </div>
      <div id="sug-add-section" class="form-group" style="margin-bottom:12px">
        <label>New value to add</label>
        <input type="text" id="sug-new-value" placeholder="Enter value..."
          style="width:100%;padding:10px;border:1.5px solid var(--border);border-radius:7px;font-size:14px;margin-top:4px">
      </div>
      <div id="sug-remove-section" class="form-group" style="margin-bottom:12px;display:none">
        <label>Select item to remove</label>
        <select id="sug-remove-idx" style="width:100%;padding:10px;border:1.5px solid var(--border);border-radius:7px;font-size:14px;margin-top:4px">
          ${opts}
        </select>
      </div>
      <div class="form-group" style="margin-bottom:16px">
        <label>Note (optional)</label>
        <input type="text" id="sug-note" placeholder="Reason for change..."
          style="width:100%;padding:10px;border:1.5px solid var(--border);border-radius:7px;font-size:14px;margin-top:4px">
      </div>
      <div style="display:flex;gap:10px">
        <button onclick="submitSuggestion('${type}')" class="btn-add" style="flex:1;background:var(--steel)">Send to Supervisor</button>
        <button onclick="document.getElementById('suggest-modal').remove()" class="btn-add" style="background:#aaa">Cancel</button>
      </div>
    </div>`;

  // Wire radio buttons
  modal.querySelectorAll('[name="sug-action"]').forEach(r => r.addEventListener('change', () => {
    const isAdd = r.value === 'add' && r.checked;
    modal.querySelector('#sug-add-section').style.display = isAdd ? '' : 'none';
    modal.querySelector('#sug-remove-section').style.display = isAdd ? 'none' : '';
  }));

  document.body.appendChild(modal);
}

function submitSuggestion(type) {
  const action = document.querySelector('[name="sug-action"]:checked')?.value || 'add';
  const note   = document.getElementById('sug-note')?.value || '';

  let value;
  if (action === 'add') {
    value = document.getElementById('sug-new-value')?.value?.trim();
    if (!value) { snack('⚠ Enter a value'); return; }
  } else {
    const idx = parseInt(document.getElementById('sug-remove-idx')?.value || '0');
    const items = type === 'parts' ? getPartsDB() : type === 'technicians' ? getTechniciansDB() :
                  type === 'trucks' ? getTrucksDB() : getEquipmentDB();
    value = items[idx];
    if (!value) { snack('⚠ Select an item'); return; }
  }

  suggestDbChange(type, action, value, note);
  document.getElementById('suggest-modal')?.remove();
}

