function superClearFilters() {
  ['sup-date-from','sup-date-to'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  ['sup-tech-filter','sup-type-filter','sup-unit-filter','sup-part-filter'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  superRender();
}

function renderSuperReports(reports) {
  const tbody = document.getElementById('sup-reports-body');
  if (!tbody) return;
  if (!reports.length) {
    tbody.innerHTML = '<tr><td colspan="7" style="padding:16px;text-align:center;color:#aaa">No reports in range</td></tr>';
    return;
  }
  tbody.innerHTML = reports.map(r => {
    const techs = (r.techs||[]).map(t=>(t.name||'').split(/\s{2,}/)[0]).filter(Boolean).join(', ');
    const col = r.status === 'completed' ? '#27ae60' : '#e67e22';
    return `<tr style="border-bottom:1px solid #eee">
      <td style="padding:6px 10px;font-weight:600;color:#1a3560;font-size:11px">${escapeHtml(r.reportNum||'')}</td>
      <td style="padding:6px 10px">${escapeHtml(r.date||'')}</td>
      <td style="padding:6px 10px">${escapeHtml(r.unit||'')}</td>
      <td style="padding:6px 10px">${escapeHtml(techs)}</td>
      <td style="padding:6px 10px;font-size:11px">${escapeHtml(r.workorder||'')}</td>
      <td style="padding:6px 10px;text-align:center">
        <span style="background:${col};color:#fff;border-radius:4px;padding:2px 8px;font-size:10px;font-weight:600">
          ${(r.status||'').toUpperCase()}
        </span>
      </td>
      <td style="padding:6px 10px;text-align:center;font-size:11px">${escapeHtml(r.type||'')}</td>
    </tr>`;
  }).join('');
}

function renderSuperParts(reports) {
  const tbody = document.getElementById('sup-parts-body');
  if (!tbody) return;
  const map = {};
  reports.forEach(r => (r.parts||[]).forEach(p => {
    if (!p.partNo) return;
    if (!map[p.partNo]) map[p.partNo] = { desc: p.desc||'', qty:0, reps: new Set() };
    map[p.partNo].qty += parseInt(p.qty||1);
    map[p.partNo].reps.add(r.reportNum);
  }));
  const entries = Object.entries(map).sort((a,b)=>b[1].qty-a[1].qty);
  if (!entries.length) {
    tbody.innerHTML = '<tr><td colspan="4" style="padding:16px;text-align:center;color:#aaa">No parts in range</td></tr>';
    return;
  }
  tbody.innerHTML = entries.map(([pn, d]) => `<tr style="border-bottom:1px solid #eee">
    <td style="padding:6px 10px;font-weight:600;font-family:monospace">${escapeHtml(pn)}</td>
    <td style="padding:6px 10px">${escapeHtml(d.desc)}</td>
    <td style="padding:6px 10px;text-align:center;font-weight:700">${d.qty}</td>
    <td style="padding:6px 10px;font-size:11px;color:#aaa">${[...d.reps].slice(0,4).join(', ')}</td>
  </tr>`).join('');
}

// Lock Out field
let lockOutActive = false;

function superExportExcel() {
  const from = document.getElementById('sup-date-from')?.value || 'all';
  const to   = document.getElementById('sup-date-to')?.value   || 'dates';
  const all  = loadSavedReports().filter(r => {
    const f = document.getElementById('sup-date-from')?.value;
    const t = document.getElementById('sup-date-to')?.value;
    if (f && r.date < f) return false;
    if (t && r.date > t) return false;
    return true;
  });

  const reportsData = [
    ['FR #','Date','Unit','Make','Model','Technician(s)','Work Order','Status','Type','C1','C2','C3'],
    ...all.map(r => [
      r.reportNum||'', r.date||'', r.unit||'', r.make||'', r.model||'',
      (r.techs||[]).map(t=>(t.name||'').split(/\s{2,}/)[0]).filter(Boolean).join('; '),
      r.workorder||'', r.status||'', r.type||'', r.c1||'', r.c2||'', r.c3||''
    ])
  ];
  const byTech = {};
  all.forEach(r => (r.techs||[]).forEach(t => {
    const name = (t.name||'').split(/\s{2,}/)[0]||'Unknown';
    if (!byTech[name]) byTech[name] = {reg:0,ot:0,reps:0};
    byTech[name].reps++;
    const h = calcHours(t.timeIn,t.timeOut);
    if (t.ot) byTech[name].ot+=h; else byTech[name].reg+=h;
  }));
  const timeData = [
    ['Technician','Reports','REG Hours','OT Hours','TOTAL'],
    ...Object.entries(byTech).map(([n,d])=>[n,d.reps,+d.reg.toFixed(2),+d.ot.toFixed(2),+(d.reg+d.ot).toFixed(2)])
  ];
  const partsMap = {};
  all.forEach(r=>(r.parts||[]).forEach(p=>{
    if (!p.partNo) return;
    if (!partsMap[p.partNo]) partsMap[p.partNo]={desc:p.desc||'',qty:0};
    partsMap[p.partNo].qty+=parseInt(p.qty||1);
  }));
  const partsData = [
    ['Part No.','Description','Total Qty'],
    ...Object.entries(partsMap).sort((a,b)=>b[1].qty-a[1].qty).map(([pn,d])=>[pn,d.desc,d.qty])
  ];

  if (typeof XLSX === 'undefined') {
    const sc = document.createElement('script');
    sc.src = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
    sc.onload = () => doExport(reportsData, timeData, partsData, from, to);
    document.head.appendChild(sc);
  } else {
    doExport(reportsData, timeData, partsData, from, to);
  }
}

function doExport(reportsData, timeData, partsData, from, to) {
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(reportsData), 'Field Reports');
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(timeData), 'Time Summary');
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(partsData), 'Parts Usage');
  XLSX.writeFile(wb, 'AirconTech_Report_' + from + '_to_' + to + '.xlsx');
  snack('✔ Excel exported');
}

