async function syncPullReports() {
  if (!_sbClient) return;
  try {
    const {data, error} = await _sbClient.from('field_reports')
      .select('report_num,data').order('updated_at', {ascending:false}).limit(200);
    if (!error && data) {
      const reports = data.map(r => ({...r.data, reportNum: r.report_num}));
      saveSavedReports(reports);
      if (document.getElementById('view-saved')?.style.display !== 'none') renderSavedList();
    }
  } catch(e) {}
}

async function syncDeleteReport(reportNum) {
  if (!_sbClient || !reportNum) return;
  try { await _sbClient.from('field_reports').delete().eq('report_num', reportNum); }
  catch(e) {}
}

// ════════════════════════════════════════
//  NUMERIC KEYPAD
// ════════════════════════════════════════
let _numpadTarget = null, _numpadValue = '';

function showNumpad(el) {
  if (window.innerWidth > 768) return; // desktop: use keyboard
  _numpadTarget = el;
  _numpadValue  = String(el.value || '');
  const d = document.getElementById('numpad-display');
  if (d) d.textContent = _numpadValue || '0';
  const pad = document.getElementById('numpad');
  if (!pad) return;
  pad.style.display = 'grid';
  const rect = el.getBoundingClientRect();
  let top = rect.bottom + 6;
  let left = rect.left;
  if (top + 280 > window.innerHeight) top = rect.top - 288;
  if (left + 244 > window.innerWidth) left = window.innerWidth - 252;
  pad.style.top = Math.max(60,top) + 'px';
  pad.style.left = Math.max(8,left) + 'px';
  document.getElementById('numpad-overlay').classList.add('active');
}
function numpadKey(k) {
  if (k === '.' && _numpadValue.includes('.')) return;
  if (_numpadValue === '0' && k !== '.') _numpadValue = k;
  else _numpadValue += k;
  document.getElementById('numpad-display').textContent = _numpadValue || '0';
}
function numpadBackspace() {
  _numpadValue = _numpadValue.slice(0,-1);
  document.getElementById('numpad-display').textContent = _numpadValue || '0';
}
function numpadClear() {
  _numpadValue = '';
  document.getElementById('numpad-display').textContent = '0';
}
function numpadConfirm() {
  if (_numpadTarget) {
    _numpadTarget.value = _numpadValue;
    _numpadTarget.dispatchEvent(new Event('input',{bubbles:true}));
    _numpadTarget.dispatchEvent(new Event('change',{bubbles:true}));
  }
  numpadClose();
}
function numpadClose() {
  const pad = document.getElementById('numpad');
  const ov  = document.getElementById('numpad-overlay');
  if (pad) pad.style.display = 'none';
  if (ov)  ov.classList.remove('active');
  _numpadTarget = null;
}
function attachNumpadToInhausInputs() {
  document.querySelectorAll('#view-inhaus input[type=number], #view-inhaus input[inputmode=decimal]').forEach(el => {
    if (!el._numpadAttached) {
      el._numpadAttached = true;
      el.addEventListener('focus', function(e) { showNumpad(this); e.preventDefault(); });
    }
  });
}

// previewSavedReport - view without editing
function previewSavedReport(idx) {
  const reports = loadSavedReports ? loadSavedReports() : [];
  const r = reports[idx];
  if (!r) return;
  const modal = document.createElement('div');
  modal.id = 'preview-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:8000;display:flex;align-items:center;justify-content:center;padding:16px';
  const inner = document.createElement('div');
  inner.style.cssText = 'background:#fff;border-radius:12px;width:100%;max-width:900px;height:92vh;display:flex;flex-direction:column;overflow:hidden';
  const bar = document.createElement('div');
  bar.style.cssText = 'display:flex;justify-content:space-between;align-items:center;padding:12px 16px;background:#1a3560;flex-shrink:0';
  bar.innerHTML = '<span style="color:#fff;font-weight:700;font-size:14px">👁 ' + (r.reportNum||'Report') + ' — ' + (r.date||'') + '</span>';
  const btns = document.createElement('div');
  btns.style.cssText = 'display:flex;gap:8px';
  const editBtn  = document.createElement('button');
  editBtn.style.cssText  = 'background:#27ae60;color:#fff;border:none;border-radius:6px;padding:7px 14px;cursor:pointer;font-weight:700';
  editBtn.textContent = '✏️ Edit';
  editBtn.onclick = () => { modal.remove(); loadReportIntoForm ? loadReportIntoForm(idx) : loadReport(idx); };
  const printBtn = document.createElement('button');
  printBtn.style.cssText = 'background:#f0a800;color:#1a3560;border:none;border-radius:6px;padding:7px 14px;cursor:pointer;font-weight:700';
  printBtn.textContent = '🖨 Print';
  printBtn.onclick = () => { if(typeof openPrintWindow==='function' && typeof generatePrintHTML==='function') openPrintWindow(generatePrintHTML(r), r.reportNum||'Report'); };
  const closeBtn = document.createElement('button');
  closeBtn.style.cssText = 'background:rgba(255,255,255,.2);color:#fff;border:none;border-radius:6px;padding:7px 14px;cursor:pointer';
  closeBtn.textContent = '✕ Close';
  closeBtn.onclick = () => modal.remove();
  [editBtn,printBtn,closeBtn].forEach(b => btns.appendChild(b));
  bar.appendChild(btns); inner.appendChild(bar);
  const body = document.createElement('div');
  body.style.cssText = 'flex:1;overflow:auto;padding:20px;background:#f5f5f5';
  const content = document.createElement('div');
  content.style.cssText = 'background:#fff;border-radius:8px;padding:20px;max-width:800px;margin:0 auto;box-shadow:0 2px 12px rgba(0,0,0,.1)';
  if (typeof generatePrintHTML === 'function') content.innerHTML = generatePrintHTML(r);
  body.appendChild(content); inner.appendChild(body);
  modal.appendChild(inner);
  modal.onclick = e => { if(e.target===modal) modal.remove(); };
  document.body.appendChild(modal);
}

