// ════════════════════════════════════════
const _supDropData = { unit: [], part: [] };
let _supActiveFilter = { unit: '', part: '' };

function supBuildDropData() {
  const allR = typeof loadSavedReports === 'function' ? loadSavedReports() : [];
  // Units
  const units = new Set();
  allR.forEach(r => { if (r.unit) units.add(r.unit); });
  if (typeof getEquipmentDB === 'function') {
    getEquipmentDB().forEach(e => { if (e.unit) units.add(e.unit); });
  }
  _supDropData.unit = [...units].sort((a,b) => a.localeCompare(b, undefined, {numeric:true}))
    .map(u => ({value: u, label: u}));

  // Parts
  const partsMap = {};
  allR.forEach(r => (r.parts||[]).forEach(p => {
    if (p.partNo && !partsMap[p.partNo]) partsMap[p.partNo] = p.desc || '';
  }));
  if (typeof getPartsDB === 'function') {
    getPartsDB().forEach(p => {
      const pn = typeof p==='string'?p:p.partNo;
      if (pn && !partsMap[pn]) partsMap[pn] = typeof p==='string'?'':(p.desc||'');
    });
  }
  _supDropData.part = Object.entries(partsMap)
    .sort((a,b) => a[0].localeCompare(b[0]))
    .map(([pn,desc]) => ({value:pn, label: pn + (desc?' — '+desc.substring(0,40):'')}));
}

function supShowDropList(type) {
  const listEl = document.getElementById('sup-'+type+'-droplist');
  if (!listEl) return;
  const searchEl = document.getElementById('sup-'+type+'-search');
  const q = searchEl ? searchEl.value.toLowerCase() : '';
  supRenderDropList(type, q);
  listEl.style.display = 'block';
  // Close on outside click
  setTimeout(() => {
    document.addEventListener('click', function handler(e) {
      if (!e.target.closest('#sup-'+type+'-droplist') && e.target.id !== 'sup-'+type+'-search') {
        listEl.style.display = 'none';
        document.removeEventListener('click', handler);
      }
    });
  }, 100);
}

function supRenderDropList(type, query) {
  const listEl = document.getElementById('sup-'+type+'-droplist');
  if (!listEl) return;
  const data   = _supDropData[type] || [];
  const active = _supActiveFilter[type];

  const filtered = query
    ? data.filter(d => d.label.toLowerCase().includes(query))
    : data;

  listEl.innerHTML = '';

  // Clear option
  const clearEl = document.createElement('div');
  clearEl.className = 'sup-droplist-clear';
  clearEl.textContent = active ? '✕ Clear: ' + active : '— All ' + (type==='unit'?'Units':'Parts') + ' —';
  clearEl.onclick = () => {
    supSetFilter(type, '');
  };
  listEl.appendChild(clearEl);

  if (!filtered.length) {
    const empty = document.createElement('div');
    empty.style.cssText = 'padding:10px 12px;font-size:12px;color:#aaa';
    empty.textContent = 'No results';
    listEl.appendChild(empty);
    return;
  }

  filtered.slice(0, 80).forEach(d => {
    const item = document.createElement('div');
    item.className = 'sup-droplist-item' + (d.value===active?' selected':'');
    item.textContent = d.label;
    item.title = d.label;
    item.onclick = () => {
      supSetFilter(type, d.value);
      listEl.style.display = 'none';
    };
    listEl.appendChild(item);
  });

  if (filtered.length > 80) {
    const more = document.createElement('div');
    more.style.cssText = 'padding:6px 12px;font-size:11px;color:#aaa;text-align:center';
    more.textContent = (filtered.length-80) + ' more — type to narrow';
    listEl.appendChild(more);
  }
}

function supSearchFilter(type, query) {
  supRenderDropList(type, query.toLowerCase());
  const listEl = document.getElementById('sup-'+type+'-droplist');
  if (listEl) listEl.style.display = 'block';
}

function supSetFilter(type, value) {
  _supActiveFilter[type] = value;
  const searchEl = document.getElementById('sup-'+type+'-search');
  const hiddenSel = document.getElementById('sup-'+type+'-filter');
  if (searchEl) searchEl.value = value;
  if (hiddenSel) hiddenSel.value = value;
  const listEl = document.getElementById('sup-'+type+'-droplist');
  if (listEl) listEl.style.display = 'none';
  superRender();
}

// Override supFilterBy to work with new searchable inputs
function supFilterBy(field, value) {
  if (field === 'unit' || field === 'part') {
    supSetFilter(field, value);
  } else {
    const fieldMap = {'tech':'sup-tech-filter','type':'sup-type-filter'};
    const el = document.getElementById(fieldMap[field]);
    if (el) { el.value = value; superRender(); }
  }
  snack('🔍 Filtered by: ' + value);
}

function unitFilterClick(unit) { supFilterBy('unit', unit); }

// Override superClearFilters
function superClearFilters() {
  ['sup-date-from','sup-date-to'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  ['sup-tech-filter','sup-type-filter'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  supSetFilter('unit','');
  supSetFilter('part','');
  superRender();
}

