// ════════════════════════════════════════
//  SUPABASE CLOUD SYNC — Direct REST API
// ════════════════════════════════════════
const SUPABASE_KEY_CONST = 'sb_publishable_uQp2rf4MOlodZUbTsN8LJA_D5CfY4Y4';


function sbHeaders() {
  return {
    'Content-Type': 'application/json',
    'apikey': SUPABASE_KEY_CONST,
    'Authorization': 'Bearer ' + SUPABASE_KEY_CONST,
    'Prefer': 'return=minimal'
  };
}

async function sbRequest(method, path, body) {
  const url = SUPABASE_URL_CONST + '/rest/v1/' + path;
  const opts = { method, headers: sbHeaders() };
  if (body) opts.body = JSON.stringify(body);
  const r = await fetch(url, opts);
  if (!r.ok && r.status !== 409) {
    const t = await r.text();
    throw new Error(r.status + ': ' + t.substring(0, 200));
  }
  const text = await r.text();
  return text ? JSON.parse(text) : null;
}

function initSupabaseWithKey(url, key) {
  setSyncStatus('connecting', '⟳ Connecting…');
  sbRequest('GET', 'field_reports?select=report_num&limit=1')
    .then(data => {
      setSyncStatus('online', '☁ Synced');
      syncPullAll().then(() => {
        const count = loadSavedReports ? loadSavedReports().length : 0;
        setSyncStatus('online', '☁ Synced');
        const ce = document.getElementById('sync-count');
        if (ce) ce.textContent = count + ' reports';
        snack('☁ Cloud sync active — ' + count + ' reports');
      });
      if (window._syncInterval) clearInterval(window._syncInterval);
      window._syncInterval = setInterval(async () => {
        try { await syncPullReports(); setSyncStatus('online', '☁ Synced'); }
        catch(e) { console.warn('Poll error:', e.message); }
      }, 30000);
    })
    .catch(e => {
      console.error('Supabase connect:', e.message);
      if (e.message.includes('does not exist') || e.message.includes('42P01')) {
        setSyncStatus('offline', '⚠ DB not set up');
        showSupabaseSetupBtn();
        if (!localStorage.getItem('sb_setup_dismissed')) setTimeout(supabaseSetupTable, 500);
      } else {
        setSyncStatus('offline', '⚠ ' + e.message.substring(0, 40));
      }
    });
}

