function printAllShiftReports() {
  var techDD = dropdownRegistry['tc-tech'];
  var techName = techDD && techDD.input ? techDD.input.value : '';
  var dateStr = document.getElementById('tc-date-start') ? document.getElementById('tc-date-start').value : '';
  var shiftDD = dropdownRegistry['tc-shift'];
  var shift = shiftDD && shiftDD.input ? shiftDD.input.value : '';
  if (!techName || !dateStr) { snack('Select technician and date in Time Card first'); switchView('tc'); return; }
  var all = loadSavedReports ? loadSavedReports() : [];
  var techClean = techName.split(/  +/)[0].trim().toLowerCase();
  var matches = all.filter(function(r) {
    if (r.date !== dateStr) return false;
    // Shift filter: relaxed - skip if either is empty
    if (shift && r.shift && r.shift.trim() && r.shift !== shift) return false;
    return (r.techs||[]).some(function(t){ return (t.name||'').split(/  +/)[0].trim().toLowerCase() === techClean; });
  }).sort(function(a,b){ return (a.savedAt||'').localeCompare(b.savedAt||''); });
  if (!matches.length) { snack('No field reports found for this shift'); return; }
  var html = '';
  matches.forEach(function(r, i) {
    if (typeof generatePrintHTML === 'function') {
      html += '<div style="' + (i > 0 ? 'page-break-before:always;' : '') + '">' + generatePrintHTML(r) + '</div>';
    }
  });
  if (typeof openPrintWindow === 'function') openPrintWindow(html, 'Reports — ' + techName);
  snack('Opening ' + matches.length + ' reports');
}

